def subsystem(path):
    if '/tests/' in path:return 'tests'
    if path.startswith('frontend/'):return 'frontend'
    if path.startswith('backend/rql_xql/'):
        return path.split('/')[2]
    if path.startswith('backend/'):return path.split('/')[1]
    return path.split('/')[0]
edges=collections.Counter((subsystem(e['source']),subsystem(e['target'])) for e in INV['edges'] if subsystem(e['source'])!=subsystem(e['target']) and 'tests' not in (subsystem(e['source']),subsystem(e['target'])))
top=[(a,b,n) for (a,b),n in edges.items() if n>=4]
graphs['imports']=('Import dependencies between subsystems','Edges show static Python import references, aggregated by subsystem; labels count references. Only cross-subsystem edges with at least four references are shown. Tests are omitted. Imports are not runtime calls, and dynamic/plugin calls are not captured.', '\n'.join(f'"{a}" -> "{b}" [label="{n}"];' for a,b,n in top))
for name,(_,_,body) in graphs.items():
    dot='digraph G { graph [rankdir=LR,bgcolor="transparent",pad="0.3",nodesep="0.45",ranksep="0.6",fontname="Helvetica",fontsize=14]; node [shape=box,style="rounded,filled",fillcolor="#f6f6f0",color="#81968d",fontcolor="#15352e",fontname="Helvetica",fontsize=13,margin="0.18,0.14"]; edge [color="#6d827b",fontcolor="#3c544c",fontname="Helvetica",fontsize=10,arrowsize=0.7];'+body+'}'
    (A/f'{name}.dot').write_text(dot)
    subprocess.run(['dot','-Tsvg',str(A/f'{name}.dot'),'-o',str(A/f'{name}.svg')],check=True)

nav=[('overview','Start here'),('maps','System maps'),('journey','Follow a query'),('compiler','The compiler'),('learning','How it learns'),('atlas','Code atlas'),('evidence','Evidence & limits')]
def shell(title,body,report=False):
    links=''.join(f'<a href="{"index.html" if report else ""}#{id}">{i:02d} <span>{label}</span></a>' for i,(id,label) in enumerate(nav,1))
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · RQL / XQL field guide</title><link rel="stylesheet" href="assets/style.css"></head><body><a class="skip" href="#main">Skip to content</a><aside class="sidebar"><a class="brand" href="index.html">RQL <span>⇄</span> XQL<small>A source-grounded field guide</small></a><nav aria-label="Guide chapters">{links}<a class="review-link" href="architecture-review.html">08 <span>Architecture review ↗</span></a></nav><div class="sidebar-foot">Repository snapshot<br><code>9f71aa3</code> · 09 Nov 2026<br><span>Local • no external assets</span></div></aside><main id="main">{body}<footer>Prepared from the checked-in project, not a live production environment. Source links open the private GitHub repository at the reviewed commit. <a href="assets/inventory.json" download>Download inventory</a> · <button class="text-button" onclick="window.print()">Print / save as PDF</button></footer></main><script src="assets/inventory.js"></script><script src="assets/review-data.js"></script><script src="assets/app.js"></script></body></html>'''

